// @vitest-environment jsdom
// generated by amp-mgui's configure from its resource/app-theme*.ts: edit that and reconfigure, not this

import { describe, expect, it } from 'vitest';
import { follow_color_scheme } from './theme';

// a MediaQueryList whose answer the test flips, as the host's emulation or the OS would
function fake_query(matches: boolean) {
    const listeners: ((e: { matches: boolean }) => void)[] = [];
    const query = {
        matches,
        addEventListener: (_: string, l: (e: { matches: boolean }) => void) => listeners.push(l),
    };
    const flip = (to: boolean) => {
        query.matches = to;
        listeners.forEach((l) => l({ matches: to }));
    };
    return { query: query as unknown as MediaQueryList, flip };
}

describe('follow_color_scheme', () => {
    it('sets data-theme while the scheme is dark, and follows it', () => {
        const root = document.createElement('html');
        const { query, flip } = fake_query(true);

        follow_color_scheme(root, query);
        expect(root.dataset.theme).toBe('dark');

        flip(false);
        expect(root.dataset.theme).toBeUndefined();

        flip(true);
        expect(root.dataset.theme).toBe('dark');
    });

    it('leaves the light theme alone', () => {
        const root = document.createElement('html');
        follow_color_scheme(root, fake_query(false).query);
        expect(root.dataset.theme).toBeUndefined();
    });

    it('keeps the light theme where there are no media queries', () => {
        const root = document.createElement('html');
        follow_color_scheme(root, undefined);
        expect(root.dataset.theme).toBeUndefined();
    });
});
